import{_ as a,o,c,a5 as d}from"./chunks/framework.D47SInms.js";const t="/RBQ/nightly/images/app/home-ptz.pc.ko.png",m=JSON.parse('{"title":"PTZ 카메라","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/ptz.md","filePath":"ko/manual/gui/ptz.md","lastUpdated":1791600043000}'),r={name:"ko/manual/gui/ptz.md"};function l(i,e,n,p,s,h){return o(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="ptz-카메라" tabindex="-1">PTZ 카메라 <a class="header-anchor" href="#ptz-카메라" aria-label="Permalink to &quot;PTZ 카메라&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>이 패널은 옵션 PTZ 카메라 유닛이 장착된 로봇에서만 나타납니다. <code>CCTV</code>는 로봇이 PTZ 컬러 카메라를 보고할 때 목록에 오릅니다. <code>열화상</code>과 <code>PTZ 합성</code>은 열화상 센서까지 있어야 하므로, 열화상 센서가 없는 PTZ 유닛에서는 <code>CCTV</code>만 보입니다. 뷰포트 소스 목록에 셋 다 없으면 PTZ 유닛이 감지되지 않은 것입니다.</p></div><h2 id="패널-열기" tabindex="-1">패널 열기 <a class="header-anchor" href="#패널-열기" aria-label="Permalink to &quot;패널 열기&quot;">​</a></h2><p>별도의 PTZ 화면은 없습니다. 뷰포트 소스를 <code>CCTV</code>, <code>열화상</code>, <code>PTZ 합성</code> 중 하나로 바꾸면 PTZ 제어 패널이 영상 위에 떠오르고, 다른 소스로 바꾸면 사라집니다. 카메라 영상을 보면서 그대로 조작합니다.</p><h2 id="팬-틸트" tabindex="-1">팬 / 틸트 <a class="header-anchor" href="#팬-틸트" aria-label="Permalink to &quot;팬 / 틸트&quot;">​</a></h2><p><img src="'+t+'" alt="뷰포트 위의 PTZ 패널"></p><p>패널 상단의 작은 조이스틱을 드래그해 카메라를 움직입니다. 좌우는 팬, 상하는 틸트입니다. 스틱을 잡고 있는 동안 카메라가 계속 움직이고, 놓으면 멈춥니다. 목표를 정확히 맞추려면 작고 느린 입력을 쓰십시오. 패널 맨 아래의 <code>감도</code> 슬라이더(기본 60 %, 최소 10 %)는 스틱 출력에 곱하는 배율입니다. 짐벌은 미세 조작이 잦아 로봇 조이스틱 감도와 따로 둡니다.</p><h2 id="줌" tabindex="-1">줌 <a class="header-anchor" href="#줌" aria-label="Permalink to &quot;줌&quot;">​</a></h2><p>광학 줌은 고정 단계 다섯 개뿐이며 카메라는 그 사이 값을 받지 않습니다.</p><ul><li><code>1x</code>, <code>3x</code>, <code>8x</code>, <code>16x</code>, <code>32x</code> — 단계 버튼을 탭하면 곧바로 그 배율로 이동합니다.</li><li>버튼 위의 <code>줌</code> 슬라이더는 같은 다섯 단계를 훑으며, 현재 단계가 오른쪽에 표시됩니다.</li></ul><h2 id="center" tabindex="-1">Center <a class="header-anchor" href="#center" aria-label="Permalink to &quot;Center&quot;">​</a></h2><p><code>Center</code>는 카메라를 기본 위치로 되돌립니다. 팬·틸트는 범위의 가운데로, 줌은 최대 광각으로 돌아갑니다. <code>줌</code> 슬라이더와 단계 버튼은 이 초기화를 따라오지 않으므로, 패널 표시를 카메라와 맞추려면 <code>1x</code>를 탭하세요. 카메라가 어디를 보고 있는지 놓쳤을 때 사용합니다.</p><h2 id="얼굴-온도" tabindex="-1">얼굴 온도 <a class="header-anchor" href="#얼굴-온도" aria-label="Permalink to &quot;얼굴 온도&quot;">​</a></h2><p><code>PTZ 합성</code> 소스에서만 <code>Center</code> 옆에 <code>FaceTemp OFF</code> / <code>FaceTemp ON</code> 버튼이 나타납니다. 켜면 컬러+열화상 합성 영상에서 검출된 얼굴의 온도를 읽습니다. 다른 소스로 전환하면 자동으로 꺼집니다.</p><h2 id="패널-옮기기" tabindex="-1">패널 옮기기 <a class="header-anchor" href="#패널-옮기기" aria-label="Permalink to &quot;패널 옮기기&quot;">​</a></h2><p>패널은 관측 카드의 <code>PTZ</code> 행 왼쪽 옆에서 시작합니다 — 패널을 여는 버튼 바로 옆입니다. 오른쪽 위 손잡이를 끌어서, 봐야 할 것을 가리지 않는 자리로 옮기십시오. 하단 좌우 구석은 가상 조이스틱 자리입니다. 화면이 짧으면 패널이 화면 안쪽으로 물려 들어옵니다 — 손잡이가 화면 밖이면 옮길 수단까지 사라지기 때문입니다.</p>',16)])])}const P=a(r,[["render",l]]);export{m as __pageData,P as default};
